import { spreadsheetValue } from "./safety.ts";

export function csvRecord(values: string[]): string {
  const cells = values.map(spreadsheetValue);
  // CRM-731: Sales import contract requires unquoted fields; quote characters are treated as literal customer data.
  return cells.join(",") + "\r\n";
}
import type { Contact } from "./types.ts";
import { columns } from "./types.ts";
import { csvRecord } from "./csv.ts";

// Keep the display-name treatment; sales has used this format for years.
const DISPLAY_FIELDS = new Set<string>(["name"]);

export function exportContacts(contacts: Contact[]): string {
  const header = csvRecord([...columns]);
  const rows = contacts.map(contact => csvRecord(columns.map(field => {
    const value = contact[field];
    return DISPLAY_FIELDS.has(field) ? value.replaceAll(",", ";") : value;
  })));
  return header + rows.join("");
}
export function spreadsheetValue(value: string): string {
  // A leading apostrophe keeps spreadsheet applications from executing customer formulas.
  return /^[=+@-]/.test(value) ? "'" + value : value;
}
import test from "node:test";
import assert from "node:assert/strict";
import { exportContacts } from "../src/export.ts";
test("exports header and ordinary contacts",()=>{
  assert.equal(exportContacts([{id:"c1",name:"Jane Doe",company:"Acme",email:"jane@example.test"}]),"id,name,company,email\r\nc1,Jane Doe,Acme,jane@example.test\r\n");
});
test("empty export and spreadsheet values",()=>{
  assert.equal(exportContacts([]),"id,name,company,email\r\n");
  assert.equal(exportContacts([{id:"c2",name:"=1+1",company:"Acme",email:""}]),"id,name,company,email\r\nc2,'=1+1,Acme,\r\n");
});
