import { spreadsheetValue } from "./safety.ts";

// RFC 4180: fields containing a delimiter, quote or line break are quoted, with embedded quotes doubled.
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  const cells = values.map(value => csvField(spreadsheetValue(value)));
  return cells.join(",") + "\r\n";
}
EOF
cat >> tests/export.test.ts <<'EOF'
test("CRM-284: company values with delimiters stay in one column",()=>{
  assert.equal(exportContacts([{id:"c3",name:"Jane Doe",company:"Acme, Inc",email:"jane@example.test"}]),"id,name,company,email\r\nc3,Jane Doe,\"Acme, Inc\",jane@example.test\r\n");
  assert.equal(exportContacts([{id:"c4",name:"Jo",company:"The \"Best\" Co\r\nLtd",email:""}]),"id,name,company,email\r\nc4,Jo,\"The \"\"Best\"\" Co\r\nLtd\",\r\n");
  assert.equal(exportContacts([{id:"c5",name:"Jo",company:"=SUM(A1,B1)",email:""}]),"id,name,company,email\r\nc5,Jo,\"'=SUM(A1,B1)\",\r\n");
});
EOF
node --version; node --test --experimental-strip-types tests/ 2>&1 | tail -15

